const readPreference=()=>{try{return localStorage.getItem('ieee-admin-theme')||'system';}catch{return 'system';}};
let db=seed(), role='super', lang='ar', viewState='normal', scenario='default', theme=readPreference();
let route='', selected=new Set(), tableCfg=null, tablePage=1, emailDraft=null, dirty=false, dialogDirty=false, currentFields=[], builderTarget=null;
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(ar,en)=>lang==='en'?(en||dictionary[ar]||ar):ar;
