const btn=(label,action,icon='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${icon?ico(icon):''}${esc(t(label))}</button>`;
const link=(label,path,icon='',cls='')=>`<a href="#/${path}" class="btn ${cls}">${icon?ico(icon):''}${esc(t(label))}</a>`;
const badge=s=>`<span class="badge ${esc(s)}">${esc(t(statuses[s]||s))}</span>`;
const date=v=>v?new Intl.DateTimeFormat(lang==='ar'?'ar-SA-u-ca-gregory':'en-GB',{day:'numeric',month:'short',year:'numeric',numberingSystem:'latn'}).format(new Date(v+'T12:00:00')):'—';
const num=v=>new Intl.NumberFormat(lang==='ar'?'ar-SA':'en-GB',{numberingSystem:'latn'}).format(v);
const today=()=>new Date().toISOString().slice(0,10);
const committee=id=>db.committees.find(x=>x.id===id)?.title||'—';
const hoursTotal=id=>db.hours.filter(x=>x.member===id).reduce((n,x)=>n+x.hours,0);
const asset=image=>image?.startsWith('/')||image?.startsWith('data:image/')?image:'/admin/assets/'+(image||'data.webp');
const nameCell=x=>`<div class="person-cell"><span class="avatar">${esc(x.name.split(' ').slice(0,2).map(w=>w[0]).join(''))}</span><div><button class="text-button name" data-action="detail" data-id="${esc(x.id)}">${esc(x.name)}</button><span class="secondary ltr-text">${esc(x.email)}</span></div></div>`;
const actionIcon=(name,action,id,label)=>`<button type="button" class="icon-button" data-action="${action}" data-id="${esc(id)}" aria-label="${esc(t(label))}" title="${esc(t(label))}">${ico(name)}</button>`;
const statusOptions=(keys,value)=>keys.map(k=>`<option value="${k}" ${k===value?'selected':''}>${esc(t(statuses[k]||k))}</option>`).join('');
const options=(items,value)=>items.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(t(v))}</option>`).join('');
const field=(label,name,value='',type='text',extra='',help='')=>`<label class="field"><span class="label">${esc(t(label))}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}>${help?`<span class="help">${esc(t(help))}</span>`:''}</label>`;
const selectField=(label,name,opts,extra='')=>`<label class="field"><span class="label">${esc(t(label))}</span><select name="${name}" ${extra}>${opts}</select></label>`;
const textarea=(label,name,value='',extra='')=>`<label class="field"><span class="label">${esc(t(label))}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const check=(label,name,checked=false)=>`<label class="check-label"><input type="checkbox" name="${name}" ${checked?'checked':''}>${esc(t(label))}</label>`;
