function showDetail(id){const area=route.split('/')[0];const x=(area==='registrations'?db.registrations:area==='applications'?db.applications:db.members).find(x=>x.id===id);if(!x)return;
 const extra=area==='members'?`<div><dt>${t('تاريخ الانضمام')}</dt><dd>${date(x.joinDate)}</dd></div><div><dt>${t('إجمالي الساعات')}</dt><dd>${num(hoursTotal(x.id))} ${t('ساعات','hours')}</dd></div>`:`<div class="full"><dt>${t('نبذة عن المتقدم')}</dt><dd>${esc(x.about||x.answer||'—')}</dd></div><div class="full"><dt>${t('الخبرات والأعمال')}</dt><dd>${esc(x.experience||'—')}</dd></div><div class="full"><dt>${t('السيرة الذاتية')}</dt><dd>${x.cv?`<a href="${esc(x.cv)}" target="_blank" class="btn small">${ico('file-text')}${t('عرض الملف')}</a>`:t('لم يرفق ملفًا')}</dd></div>`;
 const statusList=area==='members'?['active','inactive','left','removed']:['new','accepted','waitlist','rejected'];
 openDialog(area==='members'?'تفاصيل العضو':'تفاصيل الطلب',`<div class="section-title"><h3>${esc(x.name)}</h3>${badge(x.status)}</div><dl class="detail-grid"><div><dt>${t('البريد الإلكتروني')}</dt><dd class="ltr-text">${esc(x.email)}</dd></div><div><dt>${t('رقم الجوال')}</dt><dd class="ltr-text">${esc(x.phone)}</dd></div><div><dt>${t('الرقم الجامعي')}</dt><dd class="ltr-text">${esc(x.studentId)}</dd></div><div><dt>${t('التخصص')}</dt><dd>${esc(x.major)}</dd></div><div><dt>${t('اللجنة')}</dt><dd>${esc(committee(x.committee))}</dd></div>${extra}</dl>${area!=='members'?'':`<div class="space-top">${selectField('الحالة','status',statusOptions(statusList,x.status))}</div>`}`+`<div class="actions">${area!=='members'?decisionButtons(x,area):''}${area==='members'?btn('تعديل','edit-member','pencil','',`data-id="${x.id}"`):''}${btn('Email selected','detail-email','mail','',`data-id="${x.id}"`)}${btn('WhatsApp يدوي','manual-whatsapp','message-circle','',`data-id="${x.id}"`)}</div>`,area!=='members'?btn('إغلاق','close-dialog'):saveDialog('حفظ التعديلات'),area!=='members'?null:values=>{x.status=values.status;closeDialog(true);render();toast('تم تغيير الحالة');},true);
}
document.addEventListener('click',e=>{
 const a=e.target.closest('a[href^="#/"]');if(a&&dirty){if(!window.confirm(t('لديك تعديلات غير محفوظة. هل تريد المغادرة؟'))){e.preventDefault();return;}dirty=false;}
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 switch(action){
 case 'menu':$('#sidebar').classList.toggle('open');$('#scrim').hidden=!$('#sidebar').classList.contains('open');b.setAttribute('aria-expanded',String(!$('#scrim').hidden));break;
 case 'close-dialog':closeDialog();break;
 case 'language':if(dirty&&!window.confirm(t('لديك تعديلات غير محفوظة. هل تريد المغادرة؟')))break;lang=lang==='ar'?'en':'ar';dirty=false;render();break;
 case 'theme':theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme();b.innerHTML=ico(theme==='dark'?'sun':'moon');decorate();break;
 case 'logout':location.href='/cdn-cgi/access/logout';break;
 case 'normal-state':viewState='normal';render();break;
 case 'reset-data':closeDialog(true);confirmAction('إعادة ضبط البيانات',t('ستفقد جميع التعديلات التجريبية وتعود إلى بيانات البداية.','All preview edits will be replaced with the original samples.'),()=>{db=seed();scenario='default';dirty=false;viewState='normal';navigate('overview');render();});break;
 case 'page-prev':tablePage--;updateTable();break;
 case 'page-next':tablePage++;updateTable();break;
 case 'clear-filters':$('#table-search').value='';$$('[data-filter]').forEach(x=>x.value='');tablePage=1;updateTable();break;
 case 'clear-selected':selected.clear();updateTable();break;
 case 'bulk-status':{const n=selected.size,s=$('#bulk-status').value;confirmAction('تغيير الحالة',`${t('تغيير حالة','Change status for')} ${num(n)} ${t('سجلات إلى','records to')} ${t(statuses[s])}؟`,()=>{setStatuses(tableCfg.rows(),[...selected],s);selected.clear();updateTable();toast('تم تغيير الحالة');});break;}
 case 'export-all':exportRows();break;
 case 'export-selected':exportRows(true);break;
 case 'email-selected':startEmail(tableCfg.rows().filter(x=>selected.has(x.id)));break;
 case 'email-one':startEmail(tableCfg.rows().filter(x=>x.id===id));break;
 case 'detail-email':{const records=[...db.applications,...db.members,...db.registrations].filter(x=>x.id===id);closeDialog(true);startEmail(records);break;}
 case 'detail':showDetail(id);break;
 case 'edit-event':navigate('events/edit/'+id);break;
 case 'registrations':navigate('registrations/'+id);break;
 case 'share-event':navigate('events/share/'+id);break;
 case 'duplicate-event':{const original=db.events.find(x=>x.id===id);const copy={...structuredClone(original),id:uid(),title:original.title+' — '+t('نسخة','copy'),status:'draft',registration:'closed',featured:false};db.events.push(copy);render();toast('تم نسخ الفعالية');break;}
 case 'toggle-registration':{const x=db.events.find(x=>x.id===id);x.registration=x.registration==='open'?'closed':'open';render();toast('تم تغيير الحالة');break;}
 case 'preview-event':{const form=$('#page-form');const values=Object.fromEntries(new FormData(form));openDialog('معاينة',`<img class="image-preview" src="${$('#cover-preview').src}" alt=""><h2>${esc(values.title)}</h2><p class="muted small">${date(values.date)} · ${esc(values.time)} — ${date(values.end||values.date)} · ${esc(values.endTime)} · ${esc(values.location)}</p><p class="space-top">${esc(values.description)}</p><div class="space-top">${badge(values.status)} ${badge(values.registration)}</div>`,btn('إغلاق','close-dialog'));break;}
 case 'add-field':editField();break;
 case 'edit-field':editField(Number(id));break;
 case 'field-up':moveField(Number(id),-1);break;
 case 'field-down':moveField(Number(id),1);break;
 case 'delete-field':{const i=Number(id);if(currentFields.some(f=>f.condition===i)){toast(t('احذف شروط الحقول المرتبطة أولًا.','Remove dependent conditions first.'));break;}currentFields.splice(i,1);currentFields.forEach(f=>{if(f.condition>i)f.condition--;});dirty=true;renderBuilder();break;}
 case 'apply-template':confirmAction('اختيار قالب',t('استبدال الحقول الحالية بالقالب المحدد؟','Replace current fields with the selected template?'),()=>{currentFields=structuredClone(templates[$('#template-choice').value]);dirty=true;renderBuilder();});break;
 case 'save-form':builderTarget.fields=structuredClone(currentFields);dirty=false;toast('تم حفظ النموذج');break;
 case 'copy-form':download(JSON.stringify(currentFields,null,2),'application/json','form-template.json');toast(t('تم تنزيل نسخة من إعداد النموذج.','A copy of the form configuration was downloaded.'));break;
 case 'sample-file':openSampleFile();break;
 case 'manual-whatsapp':{const p=[...db.registrations,...db.applications,...db.members].find(x=>x.id===id);openDialog('WhatsApp يدوي',`<p class="note">${t('هذه وسيلة تواصل فردية يدوية؛ لا ترسل المعاينة رسالة تلقائيًا.','This is a manual, individual contact option. The preview does not send a message.')}</p><p class="ltr-text">${esc(p.phone)}</p>`,btn('نسخ الرقم','copy-phone')+btn('إغلاق','close-dialog'));$('[data-action=copy-phone]').onclick=()=>navigator.clipboard.writeText(p.phone).then(()=>toast(t('تم نسخ الرقم','Phone copied')));break;}
 default:handleMoreActions(action,id,b);
 }
});
document.addEventListener('change',e=>{if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);updateTable();}});
document.addEventListener('input',e=>{if(e.target.closest('#page-form'))dirty=true;});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('[data-action=menu]')?.setAttribute('aria-expanded','false');};
$('#preview-button').hidden=true;
window.addEventListener('hashchange',()=>{const next=location.hash.replace(/^#\/?/,'')||'overview';if(dirty&&next!==route&&!window.confirm(t('لديك تعديلات غير محفوظة. هل تريد المغادرة؟'))){history.replaceState(null,'','#/'+route);return;}render();});
window.addEventListener('beforeunload',e=>{if(dirty||dialogDirty){e.preventDefault();e.returnValue='';}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(theme==='system')applyTheme();});

function handleMoreActions(action,id,b){
 switch(action){
 case 'preview-options':previewOptions();break;
 case 'edit-cycle':navigate('membership/edit/'+id);break;
 case 'cycle-form':navigate('membership/form/'+id);break;
 case 'cycle-applications':navigate('applications/'+id);break;
 case 'toggle-cycle':{const c=db.cycles.find(x=>x.id===id);c.status=c.status==='open'?'closed':'open';render();toast('تم تغيير الحالة');break;}
 case 'add-member':editMember();break;
 case 'edit-member':editMember(id);break;

 case 'request-accept':case 'request-reject':case 'request-wait':try{decideRequest(b.dataset.area,[id],action==='request-accept'?'accepted':action==='request-reject'?'rejected':'waitlist');}catch(err){toast(err.message);}break;
 case 'edit-club':editCommittee('club');break;
 case 'accept-selected':case 'wait-selected':case 'reject-selected':{const area=route.split('/')[0],ids=[...selected].filter(id=>area!=='applications'||!db.applications.find(x=>x.id===id)?.memberId),status=action==='accept-selected'?'accepted':action==='wait-selected'?'waitlist':'rejected';if(!ids.length){toast('الأعضاء المحددون مقبولون بالفعل');break;}confirmAction(status==='accepted'?'قبول المحدد':status==='rejected'?'رفض المحدد':'قائمة انتظار',`${num(ids.length)} ${t('طلبات','applications')} · ${t(statuses[status])}. ${t('لن يُرسل بريد تلقائيًا.','No automatic email is sent.')}`,()=>decideRequest(area,ids,status));break;}
 case 'add-committee':editCommittee();break;
 case 'edit-committee':editCommittee(id);break;
 case 'committee-members':navigate('members');setTimeout(()=>{const filter=$('[data-filter=committee]');if(filter){filter.value=id;updateTable();}},30);break;
 case 'add-hours':hoursDialog();break;
 case 'member-hours':hoursDialog([id]);break;
 case 'hours-selected':hoursDialog([...selected]);break;
 case 'edit-hours':hoursDialog([],id);break;
 case 'delete-hours':confirmAction('إزالة',t('إزالة قيد الساعات؟ سيُعاد حساب إجمالي العضو.','Remove this entry? The member’s total will be recalculated.'),()=>{db.hours=db.hours.filter(x=>x.id!==id);render();toast('تم الحفظ');},'إزالة');break;
 case 'edit-article':navigate('articles/edit/'+id);break;
 case 'view-article':previewArticle(db.articles.find(x=>x.id===id));break;
 case 'preview-article':previewArticle(readArticle());break;
 case 'confirm-publish':closeDialog(true);articleSave?.();articleSave=null;break;
 case 'unpublish-article':confirmAction('إلغاء النشر',t('سيختفي المقال من الموقع العام ويبقى محفوظًا كمسودة.','The article will be hidden from the public site and kept as a draft.'),()=>{db.articles.find(x=>x.id===id).status='draft';render();toast('تم تغيير الحالة');});break;
 case 'archive-article':confirmAction('أرشفة',t('أرشفة المقال وإخفاؤه عن القراء؟','Archive this article and hide it from readers?'),()=>{db.articles.find(x=>x.id===id).status='archived';render();toast('تم تغيير الحالة');});break;
 case 'rich':{const editor=$('#rich-editor');editor.focus();if(id==='heading')document.execCommand('formatBlock',false,'h2');else if(id==='paragraph')document.execCommand('formatBlock',false,'p');else document.execCommand(id,false,null);dirty=true;break;}
 case 'rich-link':{const selection=window.getSelection(),range=selection.rangeCount?selection.getRangeAt(0).cloneRange():null;openDialog('إضافة رابط',field('الرابط','url','https://','url','required'),saveDialog(),v=>{if(!safeURL(v.url))throw Error(t('أدخل رابطًا صالحًا.','Enter a valid URL.'));closeDialog(true);$('#rich-editor').focus();if(range){const s=window.getSelection();s.removeAllRanges();s.addRange(range);}document.execCommand('createLink',false,safeURL(v.url));dirty=true;});break;}
 case 'rich-image':$('#rich-image-upload').click();break;
 case 'add-announcement':editAnnouncement();break;
 case 'edit-announcement':editAnnouncement(id);break;
 case 'toggle-announcement':{const a=db.announcements.find(x=>x.id===id);a.status=a.status==='enabled'?'disabled':'enabled';render();toast('تم تغيير الحالة');break;}
 case 'preview-announcement':{const a=db.announcements.find(x=>x.id===id);openDialog('معاينة',`<div class="note"><h2>${esc(a.title)}</h2><p class="space-top">${esc(a.text)}</p>${a.url?`<a class="btn primary space-top" href="${esc(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.button||t('عرض التفاصيل'))}</a>`:''}</div>`,btn('إغلاق','close-dialog'));break;}
 case 'remove-announcement':confirmAction('إزالة',t('إزالة الإعلان نهائيًا من المعاينة؟','Permanently remove this announcement from the preview?'),()=>{db.announcements=db.announcements.filter(x=>x.id!==id);render();toast('تم الحفظ');},'إزالة');break;
 case 'add-admin':editAdmin();break;
 case 'edit-admin':editAdmin(id);break;
 case 'toggle-admin':case 'remove-admin':{const a=db.team.find(x=>x.id===id);if(a.role==='super'&&a.status==='enabled'&&db.team.filter(x=>x.role==='super'&&x.status==='enabled').length===1){toast(t('يجب إبقاء مسؤول نظام واحد نشط على الأقل.','Keep at least one active Super Admin.'));break;}const remove=action==='remove-admin';confirmAction(remove?'إزالة':'تعديل الوصول',`${t(remove?'إزالة':a.status==='enabled'?'تعطيل':'تفعيل')} ${a.email}؟`,()=>{if(remove)db.team=db.team.filter(x=>x.id!==id);else a.status=a.status==='enabled'?'disabled':'enabled';render();toast('تم الحفظ');},remove?'إزالة':'تأكيد');break;}
 case 'email-back':emailDraft.step=1;render();break;
 case 'cancel-email':confirmAction('إلغاء',t('إلغاء كتابة الرسالة والعودة للرئيسية؟','Cancel this message and return to Overview?'),()=>{dirty=false;emailDraft=null;navigate('overview');});break;
 case 'confirm-email':simulateEmail();break;
 case 'retry-failed':{const d=db.dispatches.find(x=>x.id===id);startEmail(d.recipients.filter(x=>x.status==='Failed').map((x,i)=>({...x,id:x.id||'retry'+i})));emailDraft.subject=d.subject;emailDraft.body=d.body||emailTemplates.instructions.body;emailDraft.link=d.link||'';break;}
 case 'copy-share':navigator.clipboard.writeText($('[name=share-url]').value).then(()=>toast('تم نسخ الرابط')).catch(()=>toast(t('حدد الرابط وانسخه يدويًا.','Select and copy the link manually.')));break;
 case 'download-calendar':calendarDownload(id);break;
 case 'qr-png':qrPNG();break;
 case 'qr-svg':if(currentQR)download(currentQR.createSvgTag({cellSize:8,margin:32}),'image/svg+xml','ieee-qr.svg');break;
 case 'add-redirect':editRedirect();break;
 case 'edit-redirect':editRedirect(id);break;
 case 'toggle-redirect':{if(role!=='super'){toast(t('تعديل الروابط متاح لمسؤول النظام في المعاينة حتى حسم الصلاحيات.','Link edits are restricted to Super Admin in this preview until permissions are decided.'));break;}const r=db.redirects.find(x=>x.id===id);r.status=r.status==='enabled'?'disabled':'enabled';render();toast('تم الحفظ');break;}
 case 'redirect-qr':{const r=db.redirects.find(x=>x.id===id);openDialog('QR',`<p class="ltr-text small">ieeeimsiu.org/go/${esc(r.slug)}</p><div id="qr-preview" class="qr-preview space-top"></div>`,btn('تنزيل PNG','qr-png','download')+btn('تنزيل SVG','qr-svg','download')+btn('إغلاق','close-dialog'));renderQR('https://ieeeimsiu.org/go/'+r.slug);break;}
 }
}

function cyclesScreen(){return head('دورات القبول','افتح التقديم وتابع الطلبات في كل دورة.',link('إنشاء دورة قبول','membership/edit/new','plus','primary'))+membershipTabs()+dataTable({rows:()=>db.cycles,filters:[['status','كل الحالات',['open','closed'].map(k=>[k,statuses[k]])]],columns:[['العنوان',x=>`<a class="name" href="#/membership/edit/${x.id}">${esc(x.title)}</a><span class="secondary">${esc(x.description)}</span>`],['الفترة',x=>`${date(x.start)}<span class="secondary">${date(x.end)}</span>`],['التقديم',x=>badge(x.status)],['الطلبات',x=>`<a href="#/applications/${x.id}">${num(db.applications.filter(a=>a.cycle===x.id).length)}</a>`],['الإجراءات',x=>`<div class="table-actions">${actionIcon('pencil','edit-cycle',x.id,'تعديل')}${actionIcon('list-checks','cycle-form',x.id,'نموذج التقديم')}${actionIcon('users-round','cycle-applications',x.id,'الطلبات')}${actionIcon(x.status==='open'?'lock-keyhole':'lock-keyhole-open','toggle-cycle',x.id,x.status==='open'?'إغلاق التقديم':'فتح التقديم')}</div>`]]});}
function cycleEditor(id){const existing=db.cycles.find(x=>x.id===id),c=existing||{id:uid(),title:'',description:'',start:today(),end:today(),status:'closed',fields:[...structuredClone(templates.student),{label:'اللجنة المفضلة',type:'select',required:true,options:db.committees.map(c=>c.title).join('، ')}]};const markup=head('إنشاء / تعديل دورة',c.title||'جهّز دورة القبول قبل فتح التقديم.',existing?link('نموذج التقديم','membership/form/'+c.id,'list-checks')+link('عرض الطلبات','applications/'+c.id,'users-round'):'','membership')+membershipTabs()+`<form id="page-form"><div class="form-layout"><section class="panel"><div class="form-section"><h2>${t('دورة قبول الأعضاء')}</h2>${field('العنوان','title',c.title,'text','required')}${textarea('الوصف','description',c.description,'required')}<div class="field-grid">${field('تاريخ البداية','start',c.start,'date','required')}${field('تاريخ النهاية','end',c.end,'date','required')}</div>${selectField('التقديم','status',statusOptions(['closed','open'],c.status))}</div></section><section class="panel"><div class="form-section"><h2>${t('نموذج التقديم')}</h2><p class="small muted">${t('يمكنك إعادة استخدام نموذج دورة سابقة، ثم تعديل حقوله بعد الحفظ.','Reuse a previous cycle’s form, then edit its fields after saving.')}</p><div class="space-top">${selectField('اختيار قالب','reuse',`<option value="">${t('نموذج فعالية طلابية','Student form')}</option>`+db.cycles.filter(x=>x.id!==c.id).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join(''))}</div></div></section></div><div class="form-footer"><p>${t('فتح القبول لا يرسل بريدًا تلقائيًا.','Opening applications does not send email automatically.')}</p><button type="submit" class="btn primary">${ico('check')}${t('حفظ التعديلات')}</button></div></form>`;queueMicrotask(()=>{$('#page-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(v.end<v.start)return toast(t('تاريخ النهاية يجب ألا يسبق البداية.','End date must follow the start date.'));Object.assign(c,v);if(v.reuse)c.fields=structuredClone(db.cycles.find(x=>x.id===v.reuse).fields);if(!existing)db.cycles.push(c);dirty=false;toast('تم الحفظ');navigate('membership/edit/'+c.id);};});return markup;}
function applicationsScreen(id){const cycle=db.cycles.find(x=>x.id===id)||db.cycles[0];if(!cycle)return head('طلبات العضوية','')+emptyState('لا توجد دورة قبول','أنشئ دورة قبول أولًا.',link('إنشاء دورة قبول','membership/edit/new'));return head('طلبات العضوية',cycle.title,btn('تصدير CSV','export-all','download'), 'membership')+membershipTabs()+metrics([['الطلبات',db.applications.filter(x=>x.cycle===cycle.id).length,'inbox'],['بانتظار المراجعة',db.applications.filter(x=>x.cycle===cycle.id&&x.status==='new').length,'user-round-search'],['مقبول',db.applications.filter(x=>x.cycle===cycle.id&&x.status==='accepted').length,'circle-check'],['قائمة انتظار',db.applications.filter(x=>x.cycle===cycle.id&&x.status==='waitlist').length,'clock-3']])+dataTable({rows:()=>db.applications.filter(x=>x.cycle===cycle.id),selectable:true,email:true,export:true,exportKeys:['name','email','phone','studentId','major','committee','status','date'],acceptance:true,filters:[['status','كل الحالات',['new','accepted','waitlist','rejected'].map(k=>[k,statuses[k]])],['committee','كل اللجان',db.committees.map(x=>[x.id,x.title])]],columns:[['الاسم',nameCell],['اللجنة',x=>esc(committee(x.committee))],['التخصص',x=>esc(x.major)],['تاريخ الطلب',x=>date(x.date)],['الحالة',x=>`${badge(x.status)}${x.memberId?`<span class="secondary">${t('أُضيف إلى الأعضاء','Added to members')}</span>`:''}`],['الإجراءات',x=>`<div class="table-actions decision-actions">${decisionButtons(x,'applications')}${actionIcon('eye','detail',x.id,'تفاصيل الطلب')}</div>`]]});}
