function editMember(id){const x=db.members.find(x=>x.id===id);openDialog(x?'تفاصيل العضو':'إضافة عضو',memberForm(x),saveDialog(),v=>{if(db.members.some(m=>m.email.toLowerCase()===v.email.toLowerCase()&&m.id!==id))throw Error(t('يوجد عضو بالبريد نفسه.','A member with this email already exists.'));if(x)Object.assign(x,v);else db.members.push({...v,role:'عضو',id:uid(),joinDate:new Date().toISOString().slice(0,10)});closeDialog(true);render();toast('تم الحفظ');});}
function leadershipLabel(scope,key){const v=scope==='club'?db.clubLeadership:null;const m=scope==='club'?db.members.find(x=>x.id===v?.[key]):db.members.find(x=>x.committee===scope&&(key==='leader'?['قائد','قائدة']:['نائب','نائبة']).includes(x.role));return m?`${t(scope==='club'?v[key+'Role']:m.role)} · ${esc(m.name)}`:t('لم يُعيّن بعد','Not assigned yet');}
function committeesScreen(){return head('اللجان والقادة','اللجان الأربع وقيادة النادي. مناصب القيادة مستقلة عن صلاحيات الإدارة.')+membershipTabs()+panel('قيادة النادي',`<div class="panel-body"><div class="detail-grid"><div><b>${t('قائد / قائدة النادي','Club leader')}</b><p>${leadershipLabel('club','leader')}</p></div><div><b>${t('نائب / نائبة النادي','Club deputy')}</b><p>${leadershipLabel('club','deputy')}</p></div></div><div class="space-top">${btn('تعديل قيادة النادي','edit-club','pencil')}</div></div>`)+dataTable({rows:()=>db.committees,columns:[['اسم اللجنة',x=>`<b>${esc(x.title)}</b><span class="secondary">${esc(x.description)}</span>`],['الأعضاء',x=>num(db.members.filter(m=>m.committee===x.id).length)],['القائد / القائدة',x=>leadershipLabel(x.id,'leader')],['النائب / النائبة',x=>leadershipLabel(x.id,'deputy')],['الإجراءات',x=>`<div class="table-actions">${actionIcon('pencil','edit-committee',x.id,'تعديل')}${actionIcon('users-round','committee-members',x.id,'الأعضاء')}</div>`]]});}
function editCommittee(id){const club=id==='club',c=db.committees.find(x=>x.id===id);if(!club&&!c)return;const assigned=key=>club?db.clubLeadership?.[key]:db.members.find(x=>x.committee===id&&(key==='leader'?['قائد','قائدة']:['نائب','نائبة']).includes(x.role))?.id;const title=key=>club?db.clubLeadership?.[key+'Role']:db.members.find(x=>x.id===assigned(key))?.role;const pick=(key,label)=>selectField(label,key,`<option value="">${t('لم يُعيّن بعد','Not assigned yet')}</option>`+options(db.members.filter(x=>x.status==='active').map(x=>[x.id,x.name]),assigned(key)));openDialog(club?'قيادة النادي':c.title,`<p class="note">${t('تعيين القيادة لا يمنح صلاحيات دخول الإدارة.','Leadership does not grant admin access.')}</p>`+(club?'':textarea('الوصف','description',c.description))+`<div class="field-grid">${pick('leader','القائد / القائدة')}${selectField('المسمى','leaderRole',options([['قائد','قائد'],['قائدة','قائدة']],title('leader')||'قائد'))}${pick('deputy','النائب / النائبة')}${selectField('المسمى','deputyRole',options([['نائب','نائب'],['نائبة','نائبة']],title('deputy')||'نائب'))}</div>`,saveDialog(),v=>{assignLeadership(db,id,v);if(c)c.description=v.description;closeDialog(true);render();toast('تم الحفظ');});}
function hoursScreen(){return head('الساعات التطوعية','قيود مرتبطة بالأعضاء والأنشطة، وإجماليات محسوبة.',btn('تصدير CSV','export-all','download')+btn('إضافة ساعات','add-hours','plus','primary'))+membershipTabs()+metrics([['إجمالي الساعات',db.hours.reduce((n,x)=>n+x.hours,0),'clock-3'],['القيود',db.hours.length,'list-checks'],['أعضاء لديهم ساعات',new Set(db.hours.map(x=>x.member)).size,'users-round'],['الأنشطة',new Set(db.hours.map(x=>x.activity)).size,'calendar-check']])+dataTable({hourValue:x=>x.hours,rows:()=>db.hours.map(h=>({...h,name:db.members.find(x=>x.id===h.member)?.name||'—'})),export:true,exportKeys:['name','activity','hours','date','period'],filters:[['member','كل الأعضاء',db.members.map(x=>[x.id,x.name])]],columns:[['الاسم',x=>`<b>${esc(x.name)}</b>`],['النشاط / السبب',x=>esc(x.activity)],['عدد الساعات',x=>`<b class="ltr-text">${num(x.hours)}</b>`],['التاريخ',x=>date(x.date)],['الفترة',x=>esc(x.period)],['الإجراءات',x=>`<div class="table-actions">${actionIcon('pencil','edit-hours',x.id,'تعديل')}${actionIcon('trash-2','delete-hours',x.id,'إزالة')}</div>`]]});}
function hoursDialog(ids=[],entryId){const entry=db.hours.find(x=>x.id===entryId),chosen=entry?[entry.member]:ids;openDialog(entry?'تعديل':'إضافة ساعات',`<p class="small muted">${t('تُسجّل الساعات مباشرة كقيد. مسار الاعتماد لم يُحسم بعد.','Hours are recorded directly as an entry. An approval workflow is not decided yet.')}</p><div class="field space-top"><span class="label">${t('اختيار الأعضاء')}</span><div class="recipient-list">${db.members.map(x=>`<label class="check-label"><input type="checkbox" name="member" value="${x.id}" ${chosen.includes(x.id)?'checked':''} ${entry?'disabled':''}>${esc(x.name)}<span class="muted small">${esc(committee(x.committee))}</span></label>`).join('')}</div></div>`+textarea('النشاط / السبب','activity',entry?.activity||'','required')+`<div class="field-grid">${field('عدد الساعات','hours',entry?.hours||'','number','required min="0.25" max="24" step="0.25"')}${field('التاريخ','date',entry?.date||today(),'date','required')}</div>`+field('الفصل / الفترة','period',entry?.period||'الفصل الأول 1448','text','required'),saveDialog(),(v,form)=>{const members=entry?[entry.member]:new FormData(form).getAll('member');if(entry){const hours=Number(v.hours);if(!Number.isFinite(hours)||hours<=0||hours>24)throw Error('أدخل ساعات بين 0 و24.');Object.assign(entry,v,{hours});closeDialog(true);render();toast('تم الحفظ');}else{if(!members.length)throw Error(t('اختر عضوًا واحدًا على الأقل.','Select at least one member.'));closeDialog(true);confirmAction('إضافة ساعات',`${num(v.hours)} ${t('ساعات لكل عضو من','hours for each of')} ${num(members.length)} ${t('أعضاء','members')} · ${v.activity}`,()=>{addHours(db,members,v);selected.clear();render();toast('تمت إضافة الساعات');});}});}
