function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function safeHTML(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','H2','H3','STRONG','B','EM','I','U','UL','OL','LI','A','BR','BLOCKQUOTE','IMG']);for(const el of [...doc.body.querySelectorAll('*')]){if(!allowed.has(el.tagName)){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG'].includes(el.tagName))el.remove();else el.replaceWith(...el.childNodes);continue;}const href=el.getAttribute('href'),src=el.getAttribute('src'),alt=el.getAttribute('alt');for(const attr of [...el.attributes])el.removeAttribute(attr.name);if(el.tagName==='A'&&safeURL(href)){el.setAttribute('href',safeURL(href));el.setAttribute('rel','noopener noreferrer');}if(el.tagName==='IMG'){const isLocal=/^\/(?:media\/[a-zA-Z0-9-]+|admin\/assets\/[a-zA-Z0-9/_\-.]+)$/.test(src||'');if(isLocal||/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(src||'')){el.setAttribute('src',src);el.setAttribute('alt',alt||'');}else el.remove();}}return doc.body.innerHTML;}
